// Same behavior as esm.js on purpose: Node's own runtime resolution uses
// "main" (this file) while bundlers and the star walk prefer "module", and
// the e2e legs must pass identically through either. Which file the walk
// picks is pinned separately by the engine-parity resolveModule test.
'use strict'
module.exports.plainGreet = function plainGreet(name) {
  return 'plain:' + name
}
